import os
import json
import base64
import mimetypes
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


STANDARD_SCHEMA = {
    "vendor_name": None,
    "invoice_number": None,
    "invoice_date": None,
    "due_date": None,
    "currency": None,
    "total_amount": None,
    "subtotal_amount": None,
    "tax_amount": None,
    "payment_terms": None,
    "purchase_order": None,
    "billing_address": None,
    "shipping_address": None,
    "line_items": [],
    "confidence": None,
    "raw_fields": {},
}


def _to_text(value: Any) -> Any:
    if value is None:
        return None
    if isinstance(value, str):
        return value
    if hasattr(value, "content"):
        return value.content
    if hasattr(value, "value"):
        return _to_text(value.value)
    return str(value)


def _date_to_iso(value: Any) -> Optional[str]:
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        try:
            return value.isoformat()
        except Exception:
            pass
    text = _to_text(value)
    return text


def _money_to_number(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if hasattr(value, "amount"):
        try:
            return float(value.amount)
        except Exception:
            pass
    text = _to_text(value)
    if text is None:
        return None
    cleaned = "".join(ch for ch in str(text) if ch.isdigit() or ch in ".-")
    try:
        return float(cleaned) if cleaned not in ("", "-", ".", "-.") else None
    except Exception:
        return None


def _address_to_string(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        return value
    parts: List[str] = []
    for attr in ("street_address", "streetAddress", "house_number", "city", "state", "postal_code", "postalCode", "country_region", "countryRegion"):
        if hasattr(value, attr):
            v = getattr(value, attr)
            if v:
                parts.append(_to_text(v))
    if parts:
        return ", ".join([p for p in parts if p])
    return _to_text(value)


def _extract_line_items(doc: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    fields = getattr(doc, "fields", {}) or {}
    line_items_field = fields.get("Items") or fields.get("LineItems") or fields.get("lineItems")
    candidates = []
    if line_items_field is not None and hasattr(line_items_field, "value"):
        candidates = line_items_field.value or []
    elif isinstance(line_items_field, list):
        candidates = line_items_field

    for item in candidates:
        item_fields = getattr(item, "value", None)
        if item_fields is None and hasattr(item, "fields"):
            item_fields = item.fields
        item_fields = item_fields or {}
        items.append(
            {
                "description": _to_text(item_fields.get("Description") or item_fields.get("description")),
                "quantity": _money_to_number(item_fields.get("Quantity") or item_fields.get("quantity")),
                "unit_price": _money_to_number(item_fields.get("UnitPrice") or item_fields.get("unitPrice") or item_fields.get("unit_price")),
                "amount": _money_to_number(item_fields.get("Amount") or item_fields.get("amount")),
                "raw_fields": {k: _to_text(v) for k, v in item_fields.items()},
            }
        )
    return items


def normalize_expense_fields(document: Any) -> Dict[str, Any]:
    fields = getattr(document, "fields", {}) or {}

    def field(*names: str) -> Any:
        for name in names:
            if name in fields:
                return fields[name]
        return None

    vendor_name = field("VendorName", "MerchantName", "vendorName", "merchantName")
    invoice_number = field("InvoiceId", "InvoiceNumber", "invoiceId", "invoiceNumber")
    invoice_date = field("InvoiceDate", "invoiceDate")
    due_date = field("DueDate", "dueDate")
    currency = field("Currency", "currency")
    total_amount = field("InvoiceTotal", "Total", "invoiceTotal", "total")
    subtotal_amount = field("SubTotal", "Subtotal", "subTotal", "subtotal")
    tax_amount = field("TotalTax", "Tax", "totalTax", "tax")
    payment_terms = field("PaymentTerms", "paymentTerms")
    purchase_order = field("PurchaseOrder", "PurchaseOrderNumber", "purchaseOrder", "purchaseOrderNumber")
    billing_address = field("BillingAddress", "billingAddress")
    shipping_address = field("ShippingAddress", "shippingAddress")

    normalized = dict(STANDARD_SCHEMA)
    normalized["vendor_name"] = _to_text(vendor_name)
    normalized["invoice_number"] = _to_text(invoice_number)
    normalized["invoice_date"] = _date_to_iso(invoice_date)
    normalized["due_date"] = _date_to_iso(due_date)
    normalized["currency"] = _to_text(currency)
    normalized["total_amount"] = _money_to_number(total_amount)
    normalized["subtotal_amount"] = _money_to_number(subtotal_amount)
    normalized["tax_amount"] = _money_to_number(tax_amount)
    normalized["payment_terms"] = _to_text(payment_terms)
    normalized["purchase_order"] = _to_text(purchase_order)
    normalized["billing_address"] = _address_to_string(billing_address)
    normalized["shipping_address"] = _address_to_string(shipping_address)
    normalized["line_items"] = _extract_line_items(document)

    confidences = []
    raw_fields = {}
    for k, v in fields.items():
        raw_fields[k] = _to_text(v)
        if hasattr(v, "confidence") and v.confidence is not None:
            try:
                confidences.append(float(v.confidence))
            except Exception:
                pass
    normalized["raw_fields"] = raw_fields
    normalized["confidence"] = sum(confidences) / len(confidences) if confidences else None
    return normalized


def _read_document_bytes(source: Any) -> bytes:
    if isinstance(source, bytes):
        return source
    if hasattr(source, "read"):
        return source.read()
    if isinstance(source, str):
        if source.startswith("data:"):
            return base64.b64decode(source.split(",", 1)[1])
        if os.path.exists(source):
            with open(source, "rb") as f:
                return f.read()
        return source.encode("utf-8")
    raise TypeError("Unsupported document source type")


def extract_expense_json(document_source: Any) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    doc_bytes = _read_document_bytes(document_source)
    content_type = None
    if isinstance(document_source, str) and os.path.exists(document_source):
        content_type = mimetypes.guess_type(document_source)[0]
    content_type = content_type or "application/pdf"

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=doc_bytes,
        content_type=content_type,
    )
    result = poller.result()

    docs = getattr(result, "documents", None) or []
    if not docs:
        return dict(STANDARD_SCHEMA)
    return normalize_expense_fields(docs[0])


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python script.py <document_path>")
    output = extract_expense_json(sys.argv[1])
    print(json.dumps(output, ensure_ascii=False, indent=2))
